// TypeScript port of assembler-deprecated.py. The pipeline (and its quirks) is kept the same so the
// output matches what the real assembler produces, with proper diagnostics added on top.

import { INSTRUCTIONS_BY_NAME, RAM_SIZE, ROM_SIZE } from './isa';

export interface Diagnostic {
	severity: 'error' | 'warning';
	/** 1-based source line, 0 if not tied to a line. */
	line: number;
	message: string;
}

export interface Program {
	rom: Uint32Array;
	ram: Uint16Array;
	/** ROM address -> 1-based source line (0 = generated by the assembler). */
	lineOfAddr: Int32Array;
	/** 1-based source line -> first ROM address generated from it. */
	addrOfLine: Map<number, number>;
	/** User labels pointing into ROM (name includes the leading dot). */
	romLabels: Map<string, number>;
	/** User labels pointing into RAM (DW). */
	ramLabels: Map<string, number>;
}

export interface AssembleResult {
	program: Program | null;
	diagnostics: Diagnostic[];
}

class AsmError extends Error {
	line: number;
	constructor(line: number, message: string) {
		super(message);
		this.line = line;
	}
}

interface Item {
	op: string[];
	labels: string[];
	line: number;
}

const GENERATED_PREFIX = '.__generated_label_';

function parseIntLiteral(text: string, line: number): number {
	let value: number;
	if (/^0x[0-9a-f_]+$/.test(text)) value = parseInt(text.slice(2).replaceAll('_', ''), 16);
	else if (/^0b[01_]+$/.test(text)) value = parseInt(text.slice(2).replaceAll('_', ''), 2);
	else if (/^0o[0-7_]+$/.test(text)) value = parseInt(text.slice(2).replaceAll('_', ''), 8);
	else if (/^[+-]?[0-9][0-9_]*$/.test(text)) value = parseInt(text.replaceAll('_', ''), 10);
	else throw new AsmError(line, `Invalid number or unknown symbol "${text}"`);
	return value;
}

export function assemble(source: string): AssembleResult {
	const diagnostics: Diagnostic[] = [];
	const warn = (line: number, message: string) =>
		diagnostics.push({ severity: 'warning', line, message });
	try {
		const program = assembleInner(source, warn);
		return { program, diagnostics };
	} catch (e) {
		if (e instanceof AsmError) {
			diagnostics.push({ severity: 'error', line: e.line, message: e.message });
			return { program: null, diagnostics };
		}
		throw e;
	}
}

function assembleInner(source: string, warn: (line: number, message: string) => void): Program {
	// --- parse ---------------------------------------------------------------------------
	let items: Item[] = [{ op: ['ldi', '$15', '8192'], labels: [], line: 0 }];
	const defines = new Map<string, string>();
	let pendingLabels: string[] = [];
	let pendingLabelLine = 0;

	const lines = source.split('\n');
	for (let i = 0; i < lines.length; i++) {
		const lineNo = i + 1;
		let text = lines[i];
		const comment = text.indexOf(';');
		if (comment >= 0) text = text.slice(0, comment);
		text = text.trim().toLowerCase();
		if (!text) continue;
		if (text.startsWith('.')) {
			if (/\s/.test(text)) throw new AsmError(lineNo, 'Label names cannot contain spaces');
			pendingLabels.push(text);
			pendingLabelLine = lineNo;
			continue;
		}
		if (text.startsWith('@define') || text.startsWith('#define')) {
			const parts = text.split(/\s+/);
			if (parts.length < 3) throw new AsmError(lineNo, 'Expected: @define NAME VALUE');
			if (defines.has(parts[1]))
				warn(lineNo, `"${parts[1]}" is already defined; this definition replaces it everywhere`);
			defines.set(parts[1], parts.slice(2).join(' '));
			continue;
		}
		items.push({ op: text.split(/\s+/), labels: pendingLabels, line: lineNo });
		pendingLabels = [];
	}
	if (pendingLabels.length)
		warn(pendingLabelLine, `Label ${pendingLabels.join(', ')} is not followed by an instruction`);
	defines.set('sp', '$15');

	// --- pull DW out of the instruction stream ------------------------------------------------
	const dwItems = items.filter((it) => it.op[0] === 'dw');
	items = items.filter((it) => it.op[0] !== 'dw');

	// --- relative addressing -> generated labels -------------------------------------------
	let generated = 0;
	const relativeToAbsolute = () => {
		items.forEach((item, index) => {
			item.op.forEach((arg, argIndex) => {
				if (!arg.startsWith('~')) return;
				const sign = arg[1];
				if (sign !== '+' && sign !== '-')
					throw new AsmError(item.line, `Relative address "${arg}" must look like ~+N or ~-N`);
				const offset = (sign === '-' ? -1 : 1) * parseIntLiteral(arg.slice(2), item.line);
				const target = index + offset;
				if (target < 0 || target >= items.length)
					throw new AsmError(item.line, `Relative jump target ${arg} is out of bounds`);
				const name = `${GENERATED_PREFIX}${++generated}`;
				item.op[argIndex] = name;
				items[target].labels.push(name);
			});
		});
	};

	relativeToAbsolute();

	// --- CAL / RET ------------------------------------------------------------------------------
	let next: Item[] = [];
	for (const item of items) {
		const { op, labels, line } = item;
		if (op[0] === 'cal') {
			if (op.length !== 2) throw new AsmError(line, 'CAL expects one argument');
			next.push({ op: ['psh', '~+2'], labels, line });
			next.push({ op: ['brn', op[1]], labels: [], line });
		} else if (op[0] === 'ret') {
			if (op.length !== 1) throw new AsmError(line, 'RET expects no arguments');
			next.push({ op: ['pop', '$14'], labels, line });
			next.push({ op: ['brn', '$14'], labels: [], line });
		} else next.push(item);
	}
	items = next;
	relativeToAbsolute();

	// --- PSH / POP ------------------------------------------------------------------------------
	next = [];
	for (const item of items) {
		const { op, labels, line } = item;
		if (op[0] === 'psh') {
			if (op.length !== 2) throw new AsmError(line, 'PSH expects one argument');
			next.push({ op: ['sub', '$15', '$15', '1'], labels, line });
			next.push({ op: ['ldi', '$14', op[1]], labels: [], line });
			next.push({ op: ['str', '$14', '$15'], labels: [], line });
		} else if (op[0] === 'pop') {
			if (op.length !== 2) throw new AsmError(line, 'POP expects one argument');
			next.push({ op: ['lod', op[1], '$15'], labels, line });
			next.push({ op: ['add', '$15', '$15', '1'], labels: [], line });
		} else next.push(item);
	}
	items = next;
	relativeToAbsolute();

	if (items.length > ROM_SIZE)
		throw new AsmError(0, `Program is ${items.length} instructions, ROM holds ${ROM_SIZE}`);

	// --- labels ---------------------------------------------------------------------------------
	const labelLocations = new Map<string, number>();
	const romLabels = new Map<string, number>();
	const ramLabels = new Map<string, number>();
	items.forEach((item, index) => {
		for (const label of item.labels) {
			if (labelLocations.has(label))
				throw new AsmError(item.line, `Label ${label} is already defined`);
			labelLocations.set(label, index);
			if (!label.startsWith(GENERATED_PREFIX)) romLabels.set(label, index);
		}
	});

	// --- DW -------------------------------------------------------------------------------------
	const ramData: number[] = [];
	for (const item of dwItems) {
		for (const label of item.labels) {
			if (labelLocations.has(label))
				throw new AsmError(item.line, `Label ${label} is already defined`);
			labelLocations.set(label, ramData.length);
			ramLabels.set(label, ramData.length);
		}
		if (item.op.length < 2) throw new AsmError(item.line, 'DW expects at least one value');
		for (let arg of item.op.slice(1)) {
			arg = defines.get(arg) ?? arg;
			const value = parseIntLiteral(arg, item.line);
			if (value > 0xffff || value < -0x8000)
				throw new AsmError(item.line, `Value ${arg} does not fit in a 16-bit word`);
			ramData.push(value & 0xffff);
		}
	}
	if (ramData.length > RAM_SIZE)
		throw new AsmError(0, `DW data is ${ramData.length} words, RAM holds ${RAM_SIZE}`);

	// --- encode ---------------------------------------------------------------------------------
	const argToInt = (arg: string, line: number): number => {
		const stripped = arg.replace(/^[r$m#p%]+/, '');
		if (stripped.startsWith('.')) {
			const location = labelLocations.get(stripped);
			if (location === undefined) throw new AsmError(line, `Label ${stripped} is not defined`);
			return location;
		}
		return parseIntLiteral(stripped, line);
	};
	const isReg = (arg: string | undefined) =>
		arg !== undefined && (arg.startsWith('$') || arg.startsWith('r'));

	const rom = new Uint32Array(items.length);
	const lineOfAddr = new Int32Array(items.length);
	const addrOfLine = new Map<number, number>();

	items.forEach((item, index) => {
		const { line } = item;
		const op = item.op.map((arg, i) => (i > 0 ? (defines.get(arg) ?? arg) : arg));
		const name = op[0];
		const info = INSTRUCTIONS_BY_NAME.get(name);
		if (!info) throw new AsmError(line, `Unknown instruction "${name.toUpperCase()}"`);
		const upper = name.toUpperCase();
		const argc = op.length - 1 - (info.hasDest ? 1 : 0);
		if (argc < 0) throw new AsmError(line, `${upper} requires a destination register`);
		if (argc < info.minArgs)
			throw new AsmError(line, `${upper} expects at least ${info.minArgs} argument(s)`);
		if (argc > info.maxArgs)
			throw new AsmError(line, `${upper} expects at most ${info.maxArgs} argument(s)`);

		let dest = 0;
		let args = op.slice(1);
		if (info.hasDest) {
			dest = argToInt(op[1], line);
			if (dest < 0 || dest > 15)
				throw new AsmError(line, `Destination "${op[1]}" is not a register (0-15)`);
			if (!isReg(op[1]))
				warn(line, `Destination "${op[1]}" is always treated as a register number`);
			args = op.slice(2);
		}
		// A label of the wrong kind is almost always a mistake: jumping into data, or loading code.
		const labelOf = (arg: string | undefined) => arg?.replace(/^[r$m#p%]+/, '') ?? '';
		if (info.opcode >= 0x20 && info.opcode <= 0x3f && ramLabels.has(labelOf(args[0])))
			warn(line, `${upper} jumps to ${labelOf(args[0])}, which is a data (DW) label, not code`);
		if ((name === 'lod' || name === 'str') && romLabels.has(labelOf(args[0])))
			warn(line, `${upper} uses ${labelOf(args[0])}, which is a code label, not a data (DW) label`);

		const aReg = isReg(args[0]);
		const bReg = isReg(args[1]);

		const range = (value: number, bits: number, text: string, reg: boolean) => {
			const max = (1 << bits) - 1;
			if (reg && (value < 0 || value > 15))
				throw new AsmError(line, `"${text}" is not a valid register (0-15)`);
			if (value > max)
				throw new AsmError(line, `Value ${text} is too large for ${bits} bits in this argument form`);
			if (value < 0) {
				if (value < -(1 << (bits - 1)))
					throw new AsmError(line, `Value ${text} is too small for ${bits} bits`);
				warn(
					line,
					`Negative value ${text} is truncated to ${bits} bits` +
						(bits < 16 ? ' and zero-extended by the CPU' : '')
				);
			}
			return value & max;
		};

		let data = 0;
		if (argc === 1) {
			data = range(argToInt(args[0], line), 16, args[0], aReg);
		} else if (argc === 2) {
			const a = argToInt(args[0], line);
			const b = argToInt(args[1], line);
			if (aReg && bReg) {
				data = (range(a, 8, args[0], true) << 8) | range(b, 8, args[1], true);
			} else if (aReg) {
				data = (range(a, 4, args[0], true) << 12) | range(b, 12, args[1], false);
			} else if (bReg) {
				// 12-bit immediate, 4-bit register: AAAAAAAAAAAABBBB
				data = (range(a, 12, args[0], false) << 4) | range(b, 4, args[1], true);
			} else {
				data = (range(a, 8, args[0], false) << 8) | range(b, 8, args[1], false);
			}
		}

		rom[index] =
			((info.opcode << 24) |
				(argc << 22) |
				((aReg ? 1 : 0) << 21) |
				((bReg ? 1 : 0) << 20) |
				(dest << 16) |
				data) >>>
			0;
		lineOfAddr[index] = line;
		if (line > 0 && !addrOfLine.has(line)) addrOfLine.set(line, index);
	});

	return {
		rom,
		ram: Uint16Array.from(ramData),
		lineOfAddr,
		addrOfLine,
		romLabels,
		ramLabels
	};
}

/** Parse a Xilinx .coe memory initialisation file into a list of words. */
export function parseCoe(text: string): number[] {
	const radixMatch = /memory_initialization_radix\s*=\s*(\d+)\s*;/i.exec(text);
	const radix = radixMatch ? parseInt(radixMatch[1], 10) : 16;
	const vectorMatch = /memory_initialization_vector\s*=([^;]*);?/i.exec(text);
	if (!vectorMatch) throw new Error('Not a .coe file: memory_initialization_vector not found');
	const words: number[] = [];
	for (const token of vectorMatch[1].split(/[\s,]+/)) {
		if (!token) continue;
		const value = parseInt(token, radix);
		if (Number.isNaN(value)) throw new Error(`Invalid value "${token}" in .coe file`);
		words.push(value);
	}
	return words;
}

/**
 * Format a memory image as a Xilinx .coe file, in the same layout as the Python assembler:
 * one hexadecimal word per line. `digits` is 8 for the ROM and 4 for the RAM. An empty image
 * gives just the two header lines.
 */
export function toCoe(words: ArrayLike<number>, digits: number): string {
	const values = Array.from(words, (word) => (word >>> 0).toString(16).padStart(digits, '0'));
	const header = 'memory_initialization_radix=16;\nmemory_initialization_vector=\n';
	return values.length ? header + values.join(',\n') + ';\n' : header;
}

/**
 * Build a Program from raw ROM (and optionally RAM) images, e.g. loaded from .coe files.
 * Source lines map 1:1 to addresses (line = address + 1), matching `disassembleListing`.
 */
export function programFromImages(romWords: number[], ramWords: number[] = []): Program {
	if (romWords.length > ROM_SIZE) throw new Error(`ROM image is larger than ${ROM_SIZE} words`);
	if (ramWords.length > RAM_SIZE) throw new Error(`RAM image is larger than ${RAM_SIZE} words`);
	return {
		rom: Uint32Array.from(romWords),
		ram: Uint16Array.from(ramWords),
		lineOfAddr: Int32Array.from(romWords, (_, addr) => addr + 1),
		addrOfLine: new Map(romWords.map((_, addr) => [addr + 1, addr])),
		romLabels: new Map(),
		ramLabels: new Map()
	};
}
